contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 drugs) public payable {
        require(drugs > 0);

        bool reverted;
        try c.seedMarket(drugs) { reverted = false; } catch { reverted = true; }

        bool initAfter = c.initialized();
        uint256 marketAfter = c.marketDrugs();

        assert(reverted || (initAfter == true && marketAfter == drugs));
    }

    receive() external payable {}
}

