contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address seedCaller) public payable {
        require(caller != address(0), "caller must not be zero");

        // Seed the market as a known caller (the test contract) so the call path is live.
        c.seedMarket{value: 0}(0);

